{
  "command": "cd src-tauri && rustup target list --installed 2>&1 | grep -i windows-msvc || echo 'TARGET NOT INSTALLED'; printf '\\n--- adding target ---\\n'; rustup target add x86_64-pc-windows-msvc 2>&1 | tail -n 5",
  "timeout": 120
}

{
  "command": "printf '=== protoc present? ===\\n'; command -v protoc || echo 'protoc NOT FOUND on PATH'; protoc --version 2>&1 | head -n 1 || true; printf '\\n=== git status (did Cargo.lock change?) ===\\n'; cd src-tauri && git status --short; printf '\\n=== cargo tree -i windows ===\\n'; cargo tree -i windows 2>&1 | tail -n 30",
  "timeout": 180
}

{
  "command": "cd src-tauri && echo '=== who needs windows@0.57.0 ==='; cargo tree -i windows@0.57.0 2>&1 | head -n 40; echo; echo '=== who needs windows@0.58.0 (top) ==='; cargo tree -i windows@0.58.0 2>&1 | head -n 20",
  "timeout": 180
}

{
  "command": "cd src-tauri && echo '=== git diff Cargo.toml ==='; git diff Cargo.toml; echo; echo '=== full git status ==='; git status --short; echo; echo '=== Cargo.lock changed? ==='; git diff --stat Cargo.lock | tail -n 3",
  "timeout": 30
}

{
  "command": "cd src-tauri && echo '=== COMMIT HASH ==='; git rev-parse HEAD; echo; echo '=== DIFF STAT ==='; git diff --stat HEAD~1 HEAD; echo; echo '=== cargo tree -i windows ==='; cargo tree -i windows 2>&1; echo; echo '=== who needs 0.57.0 ==='; cargo tree -i windows@0.57.0 2>&1 | head -n 8",
  "timeout": 120
}
